/**
 * Conformance audit against structures produced by OpenSSL.
 *
 * `test-fixtures/openssl-corpus/corpus.ts` holds ~240 valid DER files generated by OpenSSL 3
 * (see `generate.sh` there). For every file we check that pki-lite can parse it and
 * that re-encoding the parsed object gives back the original bytes, plus a handful of
 * semantic checks (verify a signature, decrypt, extract PKCS#12 items, ...).
 *
 * Cases that currently fail are registered in `KNOWN_ISSUES` and run with `test.fails`:
 * CI stays green, and as soon as the gap is closed the matching tests start failing with
 * "expected to fail", pointing at the entry to delete. What is left there are unsupported
 * algorithms that only pki-lite-crypto-extended provides (RSA PKCS#1 v1.5, 3DES, Ed448), which
 * its own corpus test covers.
 */
import { describe, expect, test } from 'vitest'
import { opensslCorpus } from '../../test-fixtures/openssl-corpus/corpus.js'
import { Certificate } from '../../src/x509/Certificate.js'
import { CertificateRequest } from '../../src/x509/CertificateRequest.js'
import { CertificateList } from '../../src/x509/CertificateList.js'
import { BasicConstraints } from '../../src/x509/extensions/BasicConstraints.js'
import { KeyUsage } from '../../src/x509/extensions/KeyUsage.js'
import { ExtKeyUsage } from '../../src/x509/extensions/ExtKeyUsage.js'
import { SubjectAltName } from '../../src/x509/extensions/SubjectAltName.js'
import { AuthorityKeyIdentifier } from '../../src/x509/extensions/AuthorityKeyIdentifier.js'
import { CRLDistributionPoints } from '../../src/x509/extensions/CRLDistributionPoints.js'
import { AuthorityInfoAccess } from '../../src/x509/extensions/AuthorityInfoAccess.js'
import { NameConstraints } from '../../src/x509/extensions/NameConstraints.js'
import { CertificatePolicies } from '../../src/x509/extensions/CertificatePolicies.js'
import { PolicyMappings } from '../../src/x509/extensions/PolicyMappings.js'
import { PolicyConstraints } from '../../src/x509/extensions/PolicyConstraints.js'
import { InhibitAnyPolicy } from '../../src/x509/extensions/InhibitAnyPolicy.js'
import { SubjectKeyIdentifier } from '../../src/keys/SubjectKeyIdentifier.js'
import { PrivateKeyInfo } from '../../src/keys/PrivateKeyInfo.js'
import { SubjectPublicKeyInfo } from '../../src/keys/SubjectPublicKeyInfo.js'
import { RSAPrivateKey } from '../../src/keys/RSAPrivateKey.js'
import { RSAPublicKey } from '../../src/keys/RSAPublicKey.js'
import { ECPrivateKey } from '../../src/keys/ECPrivateKey.js'
import { ECDSASignature } from '../../src/keys/ECDSASignature.js'
import { EncryptedPrivateKeyInfo } from '../../src/keys/EncryptedPrivateKeyInfo.js'
import { ContentInfo } from '../../src/pkcs7/ContentInfo.js'
import { SignedData } from '../../src/pkcs7/SignedData.js'
import { EnvelopedData } from '../../src/pkcs7/EnvelopedData.js'
import { AuthEnvelopedData } from '../../src/pkcs7/AuthEnvelopedData.js'
import { PFX } from '../../src/pkcs12/PFX.js'
import { OCSPRequest } from '../../src/ocsp/OCSPRequest.js'
import { OCSPResponse } from '../../src/ocsp/OCSPResponse.js'
import { TimeStampReq } from '../../src/timestamp/TimeStampReq.js'
import {
    PKIFailureInfo,
    PKIStatus,
    TimeStampResp,
} from '../../src/timestamp/TimeStampResp.js'
import { TSTInfo } from '../../src/timestamp/TSTInfo.js'

// Only browser-safe APIs here (atob, TextDecoder, ...): this file runs in both the
// node and the browser vitest projects.
const read = (family: string, file: string): Uint8Array<ArrayBuffer> =>
    Uint8Array.from(atob(opensslCorpus[family][file]), (c) => c.charCodeAt(0))
const files = (family: string) => Object.keys(opensslCorpus[family]).sort()
const hex = (b: Uint8Array) =>
    Array.from(b, (x) => x.toString(16).padStart(2, '0')).join('')

/** The data time-stamped by the TSA fixtures (generate/05-*.sh). */
const TSA_DATA = 'Hello, TSA world\n'

/** The message signed / encrypted by the CMS fixtures (generate/04-*.sh). */
const CMS_MESSAGE = 'Hello, CMS world\n'

// ---------------------------------------------------------------------------
// Known defects. `match` is tested against "<family>/<file>" and the check name.
// ---------------------------------------------------------------------------
type KnownIssue = {
    id: string
    why: string
    match: (target: string, check: string) => boolean
}

const KNOWN_ISSUES: KnownIssue[] = [
    {
        id: 'ED448-NEEDS-EXTENDED-PROVIDER',
        why:
            'Not available to the default provider: WebCrypto has no Ed448 (Ed25519 and RSA-PSS keys are ' +
            'supported). pki-lite-crypto-extended provides it and runs this fixture in its own openssl-corpus test.',
        match: (t, c) => c === 'isSelfSigned' && /key_ed448/.test(t),
    },
    {
        id: 'CMS-RSA-PKCS1V15-KEY-TRANSPORT',
        why:
            'Not available to the default provider: WebCrypto only offers RSA-OAEP, and raw RSA decryption ' +
            'plus padding checks should not be hand-rolled here. pki-lite-crypto-extended provides it (via ' +
            'node-forge) and runs these same fixtures in its own openssl-corpus test.',
        match: (t, c) =>
            c === 'envelopedData:decrypt' &&
            /ed_rsa_(3des|aes128|aes256|keyid)|ed_stream|ed_empty/.test(t),
    },
    {
        id: 'PKCS12-3DES-UNSUPPORTED',
        why:
            'Not available to the default provider (WebCrypto has no 3DES). pki-lite-crypto-extended ' +
            'provides it and runs this fixture in its own openssl-corpus test.',
        match: (t, c) => c === 'extractItems' && t === 'p12/legacy_3des.p12',
    },
]

function register(
    family: string,
    file: string,
    check: string,
    fn: () => void | Promise<void>,
) {
    const target = `${family}/${file}`
    const known = KNOWN_ISSUES.find((k) => k.match(target, check))
    const name = `${file} :: ${check}`
    if (known) {
        test.fails(`${name} [known issue: ${known.id}]`, fn)
    } else {
        test(name, fn)
    }
}

function expectRoundtrip(obj: { toDer(): Uint8Array }, der: Uint8Array) {
    expect(hex(obj.toDer())).toBe(hex(der))
}

// ---------------------------------------------------------------------------
// Certificates
// ---------------------------------------------------------------------------
const EXTENSIONS: Record<string, [string, any]> = {
    '2.5.29.19': ['basicConstraints', BasicConstraints],
    '2.5.29.15': ['keyUsage', KeyUsage],
    '2.5.29.37': ['extKeyUsage', ExtKeyUsage],
    '2.5.29.17': ['subjectAltName', SubjectAltName],
    '2.5.29.18': ['issuerAltName', SubjectAltName],
    '2.5.29.35': ['authorityKeyIdentifier', AuthorityKeyIdentifier],
    '2.5.29.14': ['subjectKeyIdentifier', SubjectKeyIdentifier],
    '2.5.29.31': ['crlDistributionPoints', CRLDistributionPoints],
    '2.5.29.46': ['freshestCRL', CRLDistributionPoints],
    '1.3.6.1.5.5.7.1.1': ['authorityInfoAccess', AuthorityInfoAccess],
    '1.3.6.1.5.5.7.1.11': ['subjectInfoAccess', AuthorityInfoAccess],
    '2.5.29.30': ['nameConstraints', NameConstraints],
    '2.5.29.32': ['certificatePolicies', CertificatePolicies],
    '2.5.29.33': ['policyMappings', PolicyMappings],
    '2.5.29.36': ['policyConstraints', PolicyConstraints],
    '2.5.29.54': ['inhibitAnyPolicy', InhibitAnyPolicy],
}

describe('OpenSSL corpus: certificates', () => {
    for (const file of files('cert')) {
        const der = read('cert', file)
        describe(file, () => {
            register('cert', file, 'parse', () => {
                Certificate.fromDer(der)
            })
            register('cert', file, 'roundtrip', () => {
                expectRoundtrip(Certificate.fromDer(der), der)
            })
            register('cert', file, 'accessors', () => {
                const cert = Certificate.fromDer(der)
                cert.getCommonName()
                cert.getSubjectAltNamesAsStrings()
                cert.getSubjectPublicKeyInfo()
                cert.getIssuerSerial()
                cert.tbsCertificate.subject.toString()
            })
            register('cert', file, 'isSelfSigned', async () => {
                expect(await Certificate.fromDer(der).isSelfSigned()).toBe(true)
            })

            let cert: Certificate | undefined
            try {
                cert = Certificate.fromDer(der)
            } catch {
                return
            }
            for (const ext of cert.tbsCertificate.extensions ?? []) {
                const known = EXTENSIONS[ext.extnID.toString()]
                if (!known) continue
                const [name, cls] = known
                register('cert', file, `ext:${name}:parse`, () => {
                    ext.extnValue.parseAs(cls)
                })
                register('cert', file, `ext:${name}:roundtrip`, () => {
                    const parsed = ext.extnValue.parseAs(cls) as {
                        toDer(): Uint8Array
                    }
                    expect(hex(parsed.toDer())).toBe(hex(ext.extnValue.bytes))
                })
            }
        })
    }

    // Semantic checks driven by the file name
    for (const file of files('cert').filter((f) => f.startsWith('bc_'))) {
        const cA = !file.startsWith('bc_false')
        const pathLen = /pathlen(\d+)/.exec(file)?.[1]
        register('cert', file, 'basicConstraints:value', () => {
            const cert = Certificate.fromDer(read('cert', file))
            const bc = cert
                .getExtensionByOid('2.5.29.19')!
                .extnValue.parseAs(BasicConstraints)
            expect(bc.cA).toBe(cA)
            expect(bc.pathLenConstraint).toBe(
                pathLen === undefined ? undefined : Number(pathLen),
            )
        })
    }
    for (const file of files('cert').filter((f) => f.startsWith('serial_'))) {
        const raw = file.slice('serial_'.length, -'.der'.length)
        const expected = BigInt(raw.startsWith('0x') ? raw : Number(raw))
        register('cert', file, 'serialNumber:value', () => {
            const bytes = Certificate.fromDer(read('cert', file)).tbsCertificate
                .serialNumber.bytes
            const hexStr = hex(bytes)
            expect(BigInt('0x' + hexStr)).toBe(expected)
            // DER: minimal, and positive (a high first bit needs a 00 prefix)
            if (bytes.length > 1 && bytes[0] === 0) {
                expect(bytes[1] & 0x80).toBe(0x80)
            }
        })
    }
})

