// ---------------------------------------------------------------------------
// Keys
// ---------------------------------------------------------------------------
const keyClass = (file: string): any =>
    file.startsWith('pkcs8_')
        ? PrivateKeyInfo
        : file.startsWith('spki_')
          ? SubjectPublicKeyInfo
          : file.startsWith('rsaprivate')
            ? RSAPrivateKey
            : file.startsWith('rsapublic')
              ? RSAPublicKey
              : file.startsWith('ecprivate')
                ? ECPrivateKey
                : file.startsWith('ecdsa_sig')
                  ? ECDSASignature
                  : EncryptedPrivateKeyInfo

describe('OpenSSL corpus: keys and signatures', () => {
    for (const file of files('key')) {
        const der = read('key', file)
        const cls = keyClass(file)
        register('key', file, 'parse', () => {
            cls.fromDer(der)
        })
        register('key', file, 'roundtrip', () => {
            expectRoundtrip(cls.fromDer(der), der)
        })
    }
})

// ---------------------------------------------------------------------------
// CMS
// ---------------------------------------------------------------------------
describe('OpenSSL corpus: CMS', () => {
    const rsaKey = () => PrivateKeyInfo.fromDer(read('key', 'pkcs8_rsa.der'))
    for (const file of files('cms')) {
        const der = read('cms', file)
        register('cms', file, 'contentInfo:parse', () => {
            ContentInfo.fromDer(der)
        })
        if (file.startsWith('sd_')) {
            register('cms', file, 'signedData:parse', () => {
                ContentInfo.fromDer(der).parseContentAs(SignedData)
            })
            if (!/_stream/.test(file)) {
                register('cms', file, 'signedData:roundtrip', () => {
                    const sd =
                        ContentInfo.fromDer(der).parseContentAs(SignedData)
                    expectRoundtrip(sd.toCms(), der)
                })
            }
            // certs-only bundles have no signers; nocerts has nothing to verify with
            if (!/certsonly|certs_crl|nocerts/.test(file)) {
                register('cms', file, 'signedData:verify', async () => {
                    const sd =
                        ContentInfo.fromDer(der).parseContentAs(SignedData)
                    const detached = sd.encapContentInfo.eContent === undefined
                    const result = await sd.verify(
                        detached
                            ? { data: new TextEncoder().encode(CMS_MESSAGE) }
                            : {},
                    )
                    expect(result.valid).toBe(true)
                })
            }
        } else if (/^(ed_rsa_gcm(_oaep)?|authenveloped)\.der$/.test(file)) {
            // AuthEnvelopedData (RFC 5083), written by `-aes-256-gcm`
            register('cms', file, 'authEnvelopedData:parse', () => {
                ContentInfo.fromDer(der).parseContentAs(AuthEnvelopedData)
            })
            register('cms', file, 'authEnvelopedData:roundtrip', () => {
                const aed =
                    ContentInfo.fromDer(der).parseContentAs(AuthEnvelopedData)
                expectRoundtrip(aed.toCms(), der)
            })
            // ... and must not be misread as plain EnvelopedData
            register('cms', file, 'envelopedData:rejected', () => {
                expect(() =>
                    ContentInfo.fromDer(der).parseContentAs(EnvelopedData),
                ).toThrow(/AuthEnvelopedData/)
            })
            // The default provider has no RSA PKCS#1 v1.5, so only the OAEP one decrypts
            // here; the others are decrypted by pki-lite-crypto-extended's corpus test.
            if (file === 'ed_rsa_gcm_oaep.der') {
                register('cms', file, 'authEnvelopedData:decrypt', async () => {
                    const aed =
                        ContentInfo.fromDer(der).parseContentAs(
                            AuthEnvelopedData,
                        )
                    const plain = await aed.decrypt(rsaKey())
                    expect(
                        new TextDecoder().decode(plain).replace(/\r\n/g, '\n'),
                    ).toBe(CMS_MESSAGE)
                })
            }
            if (file === 'ed_rsa_gcm_oaep.der') {
                register(
                    'cms',
                    file,
                    'authEnvelopedData:tampered',
                    async () => {
                        const aed =
                            ContentInfo.fromDer(der).parseContentAs(
                                AuthEnvelopedData,
                            )
                        aed.mac = aed.mac.map((b, i) => (i === 0 ? b ^ 1 : b))
                        // the authentication tag no longer matches
                        await expect(aed.decrypt(rsaKey())).rejects.toThrow()
                    },
                )
            }
        } else if (file.startsWith('ed_')) {
            register('cms', file, 'envelopedData:parse', () => {
                ContentInfo.fromDer(der).parseContentAs(EnvelopedData)
            })
            // BER (indefinite length) input is re-written as DER, so it cannot round-trip
            if (!/_stream/.test(file)) {
                register('cms', file, 'envelopedData:roundtrip', () => {
                    const ed =
                        ContentInfo.fromDer(der).parseContentAs(EnvelopedData)
                    expectRoundtrip(ed.toCms(), der)
                })
            }
            if (/^ed_(rsa|stream|empty)/.test(file)) {
                register('cms', file, 'envelopedData:decrypt', async () => {
                    const ed =
                        ContentInfo.fromDer(der).parseContentAs(EnvelopedData)
                    const plain = await ed.decrypt(rsaKey())
                    if (file !== 'ed_stream.der' && file !== 'ed_empty.der') {
                        // OpenSSL canonicalises text content to CRLF unless -binary
                        expect(
                            new TextDecoder()
                                .decode(plain)
                                .replace(/\r\n/g, '\n'),
                        ).toBe(CMS_MESSAGE)
                    }
                })
            }
        }
    }
})

// ---------------------------------------------------------------------------
// PKCS#12
// ---------------------------------------------------------------------------
describe('OpenSSL corpus: PKCS#12', () => {
    // [privateKeys, certificates]
    const expected: Record<string, [number, number]> = {
        'aes256_sha512.p12': [1, 1],
        'chain.p12': [1, 2],
        'default.p12': [1, 1],
        'ec.p12': [1, 1],
        'ed25519.p12': [1, 1],
        'iter1.p12': [1, 1],
        'keypbe_none.p12': [1, 1],
        'legacy_3des.p12': [1, 1],
        'localkeyid.p12': [1, 2],
        'nocerts.p12': [1, 0],
        'nokeys.p12': [0, 2],
        'nomac.p12': [1, 1],
        'nopass.p12': [1, 1],
    }
    for (const file of files('p12')) {
        const der = read('p12', file)
        register('p12', file, 'parse', () => {
            PFX.fromDer(der)
        })
        register('p12', file, 'roundtrip', () => {
            expectRoundtrip(PFX.fromDer(der), der)
        })
        register('p12', file, 'extractItems', async () => {
            const password = file === 'nopass.p12' ? '' : 'pw'
            const items = await PFX.fromDer(der).extractItems(password)
            expect([
                items.privateKeys.length,
                items.certificates.length,
            ]).toEqual(expected[file])
        })
    }
})

// ---------------------------------------------------------------------------
// OCSP
// ---------------------------------------------------------------------------
describe('OpenSSL corpus: OCSP', () => {
    for (const file of files('ocsp')) {
        const der = read('ocsp', file)
        const isRequest = file.startsWith('req_')
        const cls: any = isRequest ? OCSPRequest : OCSPResponse
        register('ocsp', file, 'parse', () => {
            cls.fromDer(der)
        })
        register('ocsp', file, 'roundtrip', () => {
            expectRoundtrip(cls.fromDer(der), der)
        })
        if (
            !isRequest &&
            !/malformed|internal|try_later|sig_required|unauthorized/.test(file)
        ) {
            register('ocsp', file, 'basic:parse', () => {
                const response = OCSPResponse.fromDer(der)
                const basic = response.getBasicOCSPResponse()
                expect(hex(basic.toDer())).toBe(
                    hex(response.responseBytes!.response.bytes),
                )
            })
        }
    }
})

// ---------------------------------------------------------------------------
// X.509 v1 certificates (no version field, no extensions)
// ---------------------------------------------------------------------------
describe('OpenSSL corpus: v1 certificates', () => {
    for (const file of files('cert').filter((f) => f.startsWith('v1_'))) {
        const der = read('cert', file)
        register('cert', file, 'v1:version', () => {
            const tbs = Certificate.fromDer(der).tbsCertificate
            expect(tbs.version).toBe(0)
            expect(tbs.extensions ?? []).toHaveLength(0)
        })
    }
})

// ---------------------------------------------------------------------------
// RFC 3161 time-stamping: q_* queries, r_* replies, tok_* bare tokens
// ---------------------------------------------------------------------------
describe('OpenSSL corpus: time-stamping', () => {
    /** the query each reply answers (generate/05-*.sh) */
    const queryOf: Record<string, string> = {
        'r_granted.der': 'q_sha256_nonce_cert.der',
        'r_nocerts.der': 'q_sha1.der',
        'r_no_nonce.der': 'q_sha512_no_nonce.der',
        'r_policy.der': 'q_policy.der',
        'r_full.der': 'q_sha256_nonce_cert.der',
        'r_essv2.der': 'q_sha256_nonce_cert.der',
        'r_ec.der': 'q_sha256_nonce_cert.der',
        'r_rejected.der': 'q_bad_policy.der',
        'tok_granted.der': 'q_sha256_nonce_cert.der',
        'tok_full.der': 'q_sha256_nonce_cert.der',
        'tok_ec.der': 'q_sha256_nonce_cert.der',
    }
    const HASHES: Record<string, [string, string]> = {
        sha1: ['1.3.14.3.2.26', 'SHA-1'],
        sha256: ['2.16.840.1.101.3.4.2.1', 'SHA-256'],
        sha512: ['2.16.840.1.101.3.4.2.3', 'SHA-512'],
    }
    const hashOf = (file: string) =>
        HASHES[/sha1|sha512/.exec(file)?.[0] ?? 'sha256']
    const tokenOf = (file: string) =>
        file.startsWith('tok_')
            ? ContentInfo.fromDer(read('ts', file))
            : TimeStampResp.fromDer(read('ts', file)).timeStampToken!
    const signedDataOf = (file: string) =>
        tokenOf(file).parseContentAs(SignedData)
    const tstInfoOf = (file: string) =>
        TSTInfo.fromDer(signedDataOf(file).encapContentInfo.eContent!)

    for (const file of files('ts')) {
        const der = read('ts', file)

        if (file.startsWith('q_')) {
            register('ts', file, 'query:parse', () => {
                TimeStampReq.fromDer(der)
            })
            register('ts', file, 'query:roundtrip', () => {
                expectRoundtrip(TimeStampReq.fromDer(der), der)
            })
            register('ts', file, 'query:fields', async () => {
                const query = TimeStampReq.fromDer(der)
                const [oid, webName] = hashOf(file)
                expect(query.version).toBe(1)
                expect(
                    query.messageImprint.hashAlgorithm.algorithm.toString(),
                ).toBe(oid)
                const digest = new Uint8Array(
                    await crypto.subtle.digest(
                        webName,
                        new TextEncoder().encode(TSA_DATA),
                    ),
                )
                expect(hex(query.messageImprint.hashedMessage)).toBe(
                    hex(digest),
                )
                expect(query.nonce !== undefined).toBe(!/no_nonce/.test(file))
                expect(query.certReq).toBe(
                    [
                        'q_sha256_nonce_cert.der',
                        'q_sha512_no_nonce.der',
                        'q_policy.der',
                    ].includes(file),
                )
                const policy = {
                    'q_policy.der': '1.2.3.4.2',
                    'q_bad_policy.der': '1.2.3.4.99',
                }[file]
                expect(query.reqPolicy?.toString()).toBe(policy)
            })
            continue
        }

        if (file.startsWith('r_')) {
            register('ts', file, 'reply:parse', () => {
                TimeStampResp.fromDer(der)
            })
            register('ts', file, 'reply:roundtrip', () => {
                expectRoundtrip(TimeStampResp.fromDer(der), der)
            })
        }

        if (file === 'r_rejected.der') {
            register('ts', file, 'reply:rejection', () => {
                const { status, timeStampToken } = TimeStampResp.fromDer(der)
                expect(status.status).toBe(PKIStatus.REJECTION)
                expect(status.failInfo).toBe(PKIFailureInfo.UNACCEPTED_POLICY)
                expect(timeStampToken).toBeUndefined()
            })
            continue
        }

        if (file.startsWith('r_')) {
            register('ts', file, 'reply:granted', () => {
                const response = TimeStampResp.fromDer(der)
                expect(response.status.status).toBe(PKIStatus.GRANTED)
                expect(response.timeStampToken).toBeDefined()
            })
        } else {
            register('ts', file, 'token:roundtrip', () => {
                expectRoundtrip(ContentInfo.fromDer(der), der)
            })
        }

        register('ts', file, 'token:signedData', () => {
            const sd = signedDataOf(file)
            expect(hex(sd.toDer())).toBe(hex(tokenOf(file).content!.toDer()))
        })
        register('ts', file, 'tstInfo:roundtrip', () => {
            const eContent = signedDataOf(file).encapContentInfo.eContent!
            expectRoundtrip(TSTInfo.fromDer(eContent), eContent)
        })
        register('ts', file, 'tstInfo:matchesQuery', () => {
            const info = tstInfoOf(file)
            const query = TimeStampReq.fromDer(read('ts', queryOf[file]))
            expect(info.version).toBe(1)
            expect(hex(info.messageImprint.toDer())).toBe(
                hex(query.messageImprint.toDer()),
            )
            expect(hex(info.nonce ?? new Uint8Array())).toBe(
                hex(query.nonce ?? new Uint8Array()),
            )
            expect(info.policy.toString()).toBe(
                file === 'r_policy.der' ? '1.2.3.4.2' : '1.2.3.4.1',
            )
            const full = /_full/.test(file)
            expect(info.ordering).toBe(full)
            expect(info.tsa !== undefined).toBe(full)
            expect(info.accuracy !== undefined).toBe(full)
        })
        if (file !== 'r_nocerts.der') {
            register('ts', file, 'token:verify', async () => {
                const result = await signedDataOf(file).verify({})
                expect(
                    result.valid,
                    result.valid ? '' : result.reasons.join('; '),
                ).toBe(true)
            })
        }
    }
})
